import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
// Start Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// End Google Fonts Loader



export type FintechCounterProps = Record<string, any>;

const FintechCounter: React.FC<FintechCounterProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 5,
  targetValue = 300,
  initialValue = 0,
  fontSize = 180,
  primaryColor = "#ffffff",
  successColor = "#4ade80",
  prefix = "$",
}) => {
  // Load fonts
  useFontLoader(["Inter", "JetBrains Mono"]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // --- Layout & Styling Logic ---
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Timing configuration
  // Faster entrance for modern UI feel
  const countDuration = Math.round(fps * (durationInSeconds * 0.6)); // Counting takes 60% of total duration
  const countDelay = Math.round(fps * 0.2); // Quick start
  const successTriggerFrame = countDelay + countDuration;

  // --- Animation 1: Entrance (Minimal Scale & Opacity) ---
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 15, stiffness: 80 },
  });

  const opacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // --- Animation 2: Counting Logic ---
  const rawValue = interpolate(
    frame - countDelay,
    [0, countDuration],
    [initialValue, targetValue],
    {
      easing: Easing.out(Easing.exp), // Smooth exponential easing
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  
  const displayValue = Math.round(rawValue).toLocaleString("en-US");

  // --- Animation 3: Success Pop & Color Change ---
  // Stronger spring configuration for "impactful" burst
  const successPop = spring({
    frame: frame - successTriggerFrame,
    fps,
    config: { damping: 10, stiffness: 180, mass: 1 }, 
  });

  const isSuccess = frame >= successTriggerFrame;
  
  // Scale Logic
  // Minimal scale-in (0.9 to 1) for premium feel
  const scaleEntrance = interpolate(entranceSpring, [0, 1], [0.9, 1]);
  
  // Scale Burst: Jumps significantly (spring overshoot) then settles at +0.15 (1.15x)
  const scalePop = interpolate(successPop, [0, 1], [0, 0.15]); 
  
  const currentScale = scaleEntrance + (isSuccess ? scalePop : 0);

  // Glow / Depth Logic
  const glowOpacity = interpolate(
    frame - successTriggerFrame,
    [0, 10],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "'Inter', sans-serif",
      }}
    >
      {/* Background Decor: Ambient light that shifts on success */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            background: `radial-gradient(circle at center, ${isSuccess ? successColor : primaryColor}20 0%, transparent 70%)`,
            opacity: 0.6,
            transition: "background 0.4s ease-out",
          }}
        />
      )}

      {/* Main Counter Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: `scale(${currentScale})`,
          opacity,
          transition: "none", 
        }}
      >
        <h1
          style={{
            fontSize: `${fontSize}px`,
            fontWeight: 700,
            color: isSuccess ? successColor : primaryColor,
            margin: 0,
            fontVariantNumeric: "tabular-nums", 
            letterSpacing: "-0.04em",
            lineHeight: 1,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            // Advanced text shadow for depth and glow
            textShadow: isSuccess 
              ? `0 0 ${50 * glowOpacity}px ${successColor}60, 0 10px ${30 * glowOpacity}px rgba(0,0,0,0.6)` 
              : "0 4px 10px rgba(0,0,0,0.2)",
            // CSS transition for color/shadow to smooth the boolean switch slightly
            transition: "color 0.2s cubic-bezier(0.2, 0.8, 0.2, 1), text-shadow 0.2s ease-out",
          }}
        >
          {/* Prefix: Same size and weight, tight alignment */}
          <span style={{ marginRight: "0.05em", opacity: 1 }}>
            {prefix}
          </span>
          {displayValue}
        </h1>
      </div>
    </AbsoluteFill>
  );
};

export default FintechCounter;